from collections import defaultdict
from typing import List, Optional

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Solution:
    def findFrequentTreeSum(self, root: Optional[TreeNode]) -> List[int]:
        counts = defaultdict(int)

        def dfs(node: Optional[TreeNode]) -> int:
            if not node:
                return 0
            total = node.val + dfs(node.left) + dfs(node.right)
            counts[total] += 1
            return total

        dfs(root)
        max_freq = max(counts.values())
        return [s for s, c in counts.items() if c == max_freq]

class Solution {
    unordered_map<int, int> counts;
    int maxFreq = 0;
    int dfs(TreeNode* node) {
        if (!node) return 0;
        int total = node->val + dfs(node->left) + dfs(node->right);
        int freq = ++counts[total];
        maxFreq = max(maxFreq, freq);
        return total;
    }
public:
    vector<int> findFrequentTreeSum(TreeNode* root) {
        counts.clear();
        maxFreq = 0;
        dfs(root);
        vector<int> res;
        for (auto& [val, freq] : counts) {
            if (freq == maxFreq) res.push_back(val);
        }
        return res;
    }
};

class Solution {
    private Map<Integer, Integer> counts = new HashMap<>();
    private int maxFreq = 0;

    private int dfs(TreeNode node) {
        if (node == null) return 0;
        int total = node.val + dfs(node.left) + dfs(node.right);
        int freq = counts.getOrDefault(total, 0) + 1;
        counts.put(total, freq);
        maxFreq = Math.max(maxFreq, freq);
        return total;
    }

    public int[] findFrequentTreeSum(TreeNode root) {
        counts.clear();
        maxFreq = 0;
        dfs(root);
        List<Integer> list = new ArrayList<>();
        for (Map.Entry<Integer, Integer> e : counts.entrySet()) {
            if (e.getValue() == maxFreq) list.add(e.getKey());
        }
        int[] res = new int[list.size()];
        for (int i = 0; i < list.size(); i++) res[i] = list.get(i);
        return res;
    }
}

var findFrequentTreeSum = function(root) {
    const counts = new Map();
    let maxFreq = 0;

    function dfs(node) {
        if (!node) return 0;
        const total = node.val + dfs(node.left) + dfs(node.right);
        const freq = (counts.get(total) || 0) + 1;
        counts.set(total, freq);
        maxFreq = Math.max(maxFreq, freq);
        return total;
    }

    dfs(root);
    const res = [];
    for (const [val, freq] of counts.entries()) {
        if (freq === maxFreq) res.push(val);
    }
    return res;
};
